<script setup lang="ts">
import {onBeforeUnmount, ref, watch} from 'vue';
import {api} from '../lib/api';
import {errorMessage} from '../lib/errors';
import {notify} from '../stores/notices';
import {date} from '../lib/content';
import type {CloudSave} from '../lib/types';
import LoadState from './LoadState.vue';
const props=defineProps<{accountId:string}>();
const saves=ref<CloudSave[]>([]), loading=ref(false), error=ref(''), editable=ref(false), editing=ref<CloudSave|null>(null), busy=ref(false), reason=ref(''), raw=ref('');
const values=ref({cash:0,total:0,swipes:0});
let requestId=0,controller:AbortController|null=null,editingAccount='';
const url=(account=props.accountId)=>'/staff/users/'+encodeURIComponent(account)+'/games/rublemet/saves';
const supported=(row:CloudSave)=>row.payload?.format==='rublemet/1'&&row.payload.state&&['cash','total','swipes'].every(k=>typeof row.payload.state[k]==='number'&&Number.isFinite(row.payload.state[k])&&row.payload.state[k]>=0);
const number=(n:unknown)=>typeof n==='number'&&Number.isFinite(n)?n.toLocaleString('ru-RU'):'—';
const positions=(v:unknown)=>Array.isArray(v)?v.filter(n=>typeof n==='number'&&n>0).length:0;
async function load(){const id=++requestId,account=props.accountId;controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;error.value='';try{const result=await api<{items:CloudSave[];editable:boolean}>(url(account),{private:true,signal});if(id!==requestId||account!==props.accountId)return;saves.value=result.items;editable.value=result.editable;}catch(e){if(id===requestId&&!signal.aborted)error.value=errorMessage(e)}finally{if(id===requestId)loading.value=false}}
watch(()=>props.accountId,()=>{editing.value=null;editingAccount='';saves.value=[];editable.value=false;void load()},{immediate:true});
onBeforeUnmount(()=>{requestId++;controller?.abort()});
function edit(save:CloudSave){if(!supported(save)||busy.value)return;editingAccount=props.accountId;editing.value=save;values.value={cash:save.payload.state.cash,total:save.payload.state.total,swipes:save.payload.state.swipes};raw.value=JSON.stringify(save.payload.state,null,2);reason.value='';}
async function save(){if(!editing.value||busy.value||editingAccount!==props.accountId)return;const account=editingAccount;busy.value=true;try{const state=JSON.parse(raw.value);Object.assign(state,values.value);if(!['cash','total','swipes'].every(k=>typeof state[k]==='number'&&Number.isFinite(state[k])&&state[k]>=0)||!Number.isInteger(state.swipes))throw new Error('Некорректные числовые данные.');if(state.total<state.cash)throw new Error('Баланс не может превышать общий заработок.');const row=editing.value;await api(url(account)+'/'+row.slot,{private:true,method:'PUT',body:{reason:reason.value,save:{operation_id:crypto.randomUUID(),expected_revision:row.revision,schema_version:row.schema_version,payload:{...row.payload,state}}}});if(account!==props.accountId)return;editing.value=null;await load();notify('Сохранение обновлено на сервере. Игра получит его при синхронизации; при конфликте потребуется выбор версии.');}catch(e){if(account!==props.accountId)return;notify(e instanceof SyntaxError?'В JSON есть ошибка.':e instanceof Error&&['Баланс не может превышать общий заработок.','Некорректные числовые данные.'].includes(e.message)?e.message:errorMessage(e),true)}finally{busy.value=false}}
</script>
<template><section class="player-saves"><div class="section-title"><h3>Сохранения Рублемёта</h3><button class="button secondary small" :disabled="loading||busy" @click="load">Обновить</button></div><p class="field-note">Последняя переданная игрой версия, а не баланс в реальном времени. Слот 1 — текущий прогресс. В офлайне данные на устройстве могут быть новее.</p><LoadState :loading="loading" :error="error" @retry="load"><p v-if="!saves.length" class="quiet-state">Игра ещё не передала сохранение. Нужны вход в AGL ID и сборка с синхронизацией.</p><article v-for="row in saves" :key="row.slot" class="save-slot"><h4>Слот {{row.slot}} · версия {{row.revision}}</h4><p>Последняя синхронизация: {{date(row.updated_at)}}</p><template v-if="supported(row)"><dl class="account-facts"><div><dt>Баланс</dt><dd>{{number(row.payload.state.cash)}} ₽</dd></div><div><dt>Всего заработано</dt><dd>{{number(row.payload.state.total)}} ₽</dd></div><div><dt>Взмахов</dt><dd>{{number(row.payload.state.swipes)}}</dd></div><div><dt>Вклад в сейфе</dt><dd>{{number(row.payload.state.safe?.principal??0)}} ₽</dd></div><div><dt>Открыто профессий</dt><dd>{{positions(row.payload.state.active)}}</dd></div><div><dt>Открыто бизнесов</dt><dd>{{positions(row.payload.state.passive)}}</dd></div></dl><button v-if="editable&&!editing" class="button secondary small" @click="edit(row)">Редактировать прогресс</button></template><p v-else class="muted">Сохранение прежнего формата. Автоматическое преобразование недоступно.</p></article></LoadState><form v-if="editing" class="form-stack inset-form" @submit.prevent="save"><h4>Изменение слота {{editing.slot}}</h4><label v-for="(label,key) in {cash:'Баланс, ₽',total:'Всего заработано, ₽',swipes:'Взмахов'}" :key="key">{{label}}<input v-model.number="values[key]" type="number" min="0" :step="key==='swipes'?1:'any'" required :disabled="busy"/></label><details><summary>Остальной прогресс</summary><p class="field-note">JSON содержит профессии, бизнесы, сюжет и другие данные. Три поля выше сохраняются отдельно.</p><textarea v-model="raw" rows="12" spellcheck="false" aria-label="Данные сохранения" class="mono"/></details><label>Причина изменения<textarea v-model="reason" minlength="3" maxlength="500" required rows="2"/></label><div class="button-row"><button class="button" :disabled="busy">Сохранить</button><button type="button" class="button secondary" :disabled="busy" @click="editing=null">Отмена</button></div><p class="field-note">Если игра успеет записать новую версию, сайт попросит обновить сохранение. Правка не перезапишет её молча.</p></form></section></template>
